    two_inv_sqrt_pi: pk.float = 2 * inv_sqrt_pi
    C_term1: pk.float = xi_squared * xi * inv_sqrt_pi
    c1: pk.float = 1.3333333333333333
    c2: pk.float = 0.8
    c3: pk.float = 0.2857142857142857
    c4: pk.float = 0.07407407407407407
